109	/// Assert the full documented success contract: exit 0, empty stderr, exactly
110	/// one LF-terminated JSON line equal to `expected`.
111	fn assert_proof_success(
112	    desc: &str,
113	    file_bytes: &[u8],
114	    index: &str,
115	    expected: &str,
116	) -> TempFile {
117	    let tmp = TempFile::create(file_bytes);
118	    let output = run_prove(&tmp.path, index);
119	    if output.status.code() != Some(0) {
120	        panic!(
121	            "[{desc}] prove {index} failed: status={:?}\n  stderr: {}\n  stdout: {}",
122	            output.status.code(),
123	            String::from_utf8_lossy(&output.stderr),
124	            String::from_utf8_lossy(&output.stdout),
125	        );
126	    }
127	    if !output.stderr.is_empty() {
128	        panic!(
129	            "[{desc}] successful prove wrote stderr: {}",
130	            String::from_utf8_lossy(&output.stderr)
131	        );
132	    }
133	    let stdout = String::from_utf8(output.stdout.clone())
134	        .unwrap_or_else(|e| panic!("[{desc}] stdout is not UTF-8: {e}"));
135	    if !stdout.ends_with('\n') || stdout.len() != expected.len() + 1 || stdout.as_bytes().iter().filter(|b| **b == b'\n').count() != 1 {
136	        panic!(
137	            "[{desc}] stdout must be exactly one JSON line + one trailing LF, got {:?}",
138	            stdout.as_bytes()
