224	/// Read the two input files and run an RFC 6962 inclusion check. The record
225	/// file's ENTIRE byte content is the target record: no LF splitting and no
226	/// trimming of trailing LF, space or CR; NUL and non-UTF-8 bytes take part as
227	/// they are. A zero-byte file is one empty record. The check itself is the
228	/// library entry point `roottrace::verify_membership`, so the command and
229	/// Rust callers of the library share exactly one verification path.
230	fn verify_files(
231	    record_path: &Path,
232	    proof_path: &Path,
233	    trusted_size: u64,
234	    trusted_root: &[u8; 32],
235	) -> Result<(), VerifyError> {
236	    let record = fs::read(record_path).map_err(|source| VerifyError::Read {
237	        path: record_path.to_path_buf(),
238	        source,
239	    })?;
240	    let proof_bytes = fs::read(proof_path).map_err(|source| VerifyError::Read {
241	        path: proof_path.to_path_buf(),
242	        source,
243	    })?;
244	    match roottrace::verify_membership(&record, &proof_bytes, trusted_size, trusted_root) {
245	        Ok(_) => Ok(()),
246	        Err(roottrace::VerifyError::MalformedProof(reason)) => {
247	            Err(VerifyError::MalformedProof(reason))
248	        }
249	        Err(roottrace::VerifyError::VerificationFailed(reason)) => Err(VerifyError::Failed(reason)),
250	        // parse_trusted_size rejects zero before this function is ever
251	        // called, so the library's invalid-argument case cannot occur here.
252	        Err(roottrace::VerifyError::InvalidTrustedSize) => {
253	            unreachable!("the command line only accepts a positive trusted tree size")
254	        }
255	    }
256	}
