258	/// Parse the trusted tree size given on the command line: one or more ASCII
259	/// decimal digits naming a POSITIVE 64-bit unsigned integer. Unlike a record
260	/// index, zero is not accepted (it cannot be a tree that contains a record).
261	/// Anything else (sign, whitespace, non-UTF-8 bytes, a value above u64::MAX)
262	/// is a usage error.
263	fn parse_trusted_size(arg: &OsStr) -> Option<u64> {
264	    let text = arg.to_str()?;
265	    if text.is_empty() || !text.bytes().all(|b| b.is_ascii_digit()) {
266	        return None;
267	    }
268	    let mut value: u64 = 0;
269	    for b in text.bytes() {
270	        value = value.checked_mul(10)?.checked_add(u64::from(b - b'0'))?;
271	    }
272	    if value == 0 {
273	        return None;
274	    }
275	    Some(value)
276	}
277	
278	/// Parse the trusted root given on the command line: exactly 64 lowercase
279	/// ASCII hexadecimal characters (32 bytes). Uppercase, wrong length, non-hex
280	/// or non-UTF-8 bytes are usage errors.
281	fn parse_trusted_root(arg: &OsStr) -> Option<[u8; 32]> {
282	    let text = arg.to_str()?;
283	    if text.len() != 64 || !text.bytes().all(is_lower_hex) {
284	        return None;
285	    }
286	    let bytes = text.as_bytes();
287	    let mut out = [0u8; 32];
288	    for (i, pair) in bytes.chunks_exact(2).enumerate() {
289	        out[i] = (hex_nibble(pair[0])? << 4) | hex_nibble(pair[1])?;
290	    }
291	    Some(out)
292	}
293	
294	/// Render a path for a human-readable error message. This is used ONLY in
295	/// diagnostics: the filesystem is always given the raw `Path`, never this
296	/// lossy rendering, so a file whose name contains 0xff is not confused with a
297	/// differently named file that merely displays the same way.
298	fn display_path(path: &Path) -> String {
299	    path.to_string_lossy().into_owned()
300	}
301	
302	/// Compute the batch root by streaming the file through a fixed-size buffer.
303	/// The whole file is never held in memory: each record is hashed as its bytes
304	/// arrive (a record of any length is never stored), and the only state kept
305	/// across records is `RootStream`'s subtree stack of at most 64 hashes —
306	/// O(log n) in the record count, independent of the file's byte size and of
307	/// the longest record. The root printed for a batch is exactly the one the
308	/// previous whole-file implementation computed (and the one `prove` still
309	/// commits to), because `RootStream` folds the same RFC 6962 tree as `mth`.
310	fn merkle_root_of_file(path: &Path) -> Result<[u8; 32], String> {
311	    let mut file = fs::File::open(path)
312	        .map_err(|e| format!("cannot read '{}': {e}", display_path(path)))?;
313	    // Fixed read buffer: how many bytes one read returns cannot affect the
314	    // result — read boundaries are never record boundaries.
315	    let mut buf = [0u8; 64 * 1024];
316	    let mut stream = RootStream::new();
317	    loop {
318	        match file.read(&mut buf) {
319	            Ok(0) => break,
320	            Ok(n) => stream.feed(&buf[..n]),
321	            Err(e) if e.kind() == std::io::ErrorKind::Interrupted => continue,
322	            // A failure partway through (including a directory path, whose
323	            // open succeeds but whose read fails) aborts the whole command:
324	            // the partial batch read so far is never reported as a root.
325	            Err(e) => return Err(format!("cannot read '{}': {e}", display_path(path))),
326	        }
327	    }
328	    Ok(stream.finish())
329	}
330	
331	fn proof_for_file(path: &Path, index: u64) -> Result<String, ProveError> {
332	    let data = fs::read(path)
333	        .map_err(|e| ProveError::Read(format!("cannot read '{}': {e}", display_path(path))))?;
334	    let records = split_records(&data);
335	    let size = records.len() as u64;
336	    if index >= size {
337	        return Err(ProveError::Missing(index, size));
338	    }
339	    let idx = index as usize;
340	    let (root, audit_path) = root_and_path(&records, idx);
341	    Ok(proof_json(size, index, &root, &audit_path))
342	}
343	
344	/// Read a proof file and return the one-line JSON object `inspect` prints:
345	/// only tree_size, leaf_index and root, taken straight from the proof. The
346	/// proof is parsed with the SAME full format check `verify` uses — a damaged
347	/// audit_path, a duplicate field, a zero tree size or an out-of-range index
348	/// are all rejected — but no target record and no trusted values exist here,
349	/// so no membership check is run and the returned text never says "verified".
350	fn inspect_file(path: &Path) -> Result<String, InspectError> {
351	    let proof_bytes = fs::read(path).map_err(|source| InspectError::Read {
352	        path: path.to_path_buf(),
353	        source,
354	    })?;
355	    let claims = match inspect_proof(&proof_bytes) {
356	        Ok(claims) => claims,
357	        Err(roottrace::InspectError::MalformedProof(reason)) => {
358	            return Err(InspectError::MalformedProof(reason));
359	        }
360	    };
361	    Ok(claims_json(&claims))
362	}
363	
364	/// Parse a record index: one or more ASCII decimal digits, non-negative, no
365	/// sign or whitespace, fitting in an unsigned 64-bit integer. Anything else
366	/// (including "+1", " 1", "1.0", "", "-1", or an argument that is not valid
367	/// UTF-8) is rejected as a usage error.
368	fn parse_index(arg: &OsStr) -> Option<u64> {
369	    let text = arg.to_str()?;
370	    if text.is_empty() || !text.bytes().all(|b| b.is_ascii_digit()) {
371	        return None;
372	    }
373	    let mut value: u64 = 0;
374	    for b in text.bytes() {
375	        value = value.checked_mul(10)?.checked_add(u64::from(b - b'0'))?;
376	    }
377	    Some(value)
378	}
379	
380	#[cfg(test)]
381	mod tests {
382	    use super::*;
383	    use std::os::unix::ffi::OsStrExt;
384	
385	    #[test]
386	    fn index_parsing_accepts_only_ascii_unsigned_decimal() {
387	        assert_eq!(parse_index(OsStr::new("0")), Some(0));
388	        assert_eq!(parse_index(OsStr::new("00")), Some(0));
389	        assert_eq!(parse_index(OsStr::new("123")), Some(123));
390	        assert_eq!(parse_index(OsStr::new("18446744073709551615")), Some(u64::MAX));
391	        assert_eq!(parse_index(OsStr::new("18446744073709551616")), None);
392	        assert_eq!(parse_index(OsStr::new("")), None);
393	        assert_eq!(parse_index(OsStr::new("-1")), None);
394	        assert_eq!(parse_index(OsStr::new("+1")), None);
395	        assert_eq!(parse_index(OsStr::new("1.0")), None);
396	        assert_eq!(parse_index(OsStr::new(" 1")), None);
397	        assert_eq!(parse_index(OsStr::new("1 ")), None);
398	        assert_eq!(parse_index(OsStr::new("0x1")), None);
399	        assert_eq!(parse_index(OsStr::new("①")), None);
400	        // Leading-zero overflow is still overflow.
401	        assert_eq!(parse_index(OsStr::new("0018446744073709551616")), None);
402	        // An argument that is not valid UTF-8 is a usage error, never a panic.
403	        assert_eq!(parse_index(OsStr::from_bytes(b"1\xff")), None);
404	        assert_eq!(parse_index(OsStr::from_bytes(b"\xff")), None);
405	    }
406	
407	    // --- trusted command-line arguments -------------------------------------
408	
409	    #[test]
410	    fn trusted_size_accepts_only_positive_ascii_decimal_u64() {
411	        assert_eq!(parse_trusted_size(OsStr::new("1")), Some(1));
412	        assert_eq!(parse_trusted_size(OsStr::new("09")), Some(9));
413	        assert_eq!(parse_trusted_size(OsStr::new("18446744073709551615")), Some(u64::MAX));
414	        // Zero is not a tree that can contain a record.
415	        assert_eq!(parse_trusted_size(OsStr::new("0")), None);
416	        assert_eq!(parse_trusted_size(OsStr::new("00")), None);
417	        for bad in ["", "-1", "+1", "1.0", " 1", "1 ", "0x1", "18446744073709551616", "①"] {
418	            assert_eq!(parse_trusted_size(OsStr::new(bad)), None, "size {bad:?}");
419	        }
420	        assert_eq!(parse_trusted_size(OsStr::from_bytes(b"9\xff")), None);
421	    }
422	
423	    #[test]
424	    fn trusted_root_accepts_exactly_64_lowercase_hex() {
425	        let h = hex(&roottrace::mth(&[b"a"]));
426	        let parsed = parse_trusted_root(OsStr::new(&h)).expect("valid root");
427	        assert_eq!(parsed, roottrace::mth(&[b"a"]));
428	        for bad in [
429	            "",
430	            &"a".repeat(63),
431	            &"a".repeat(65),
432	            // One uppercase digit.
433	            &{
434	                let mut s = h.clone();
435	                s.replace_range(0..1, "A");
436	                s
437	            },
438	            &format!("{h} "),
439	            &format!(" {h}"),
440	            &"z".repeat(64),
441	        ] {
442	            assert!(parse_trusted_root(OsStr::new(bad)).is_none(), "root {bad:?}");
443	        }
444	        assert!(parse_trusted_root(OsStr::from_bytes(&[b'a'; 65])).is_none());
445	    }
446	}
