fn batch_records<'a>(pad: &'a [u8], long: &'a [u8]) -> Vec<&'a [u8]> {
    vec![
        b"alpha",
        b"",
        pad,
        b"",
        long,
        b"beta\r",
        b"alpha",
        b"",
        b"\xff\x00z",
        b"end-record\x01",
    ]
}

